import math, re
from typing import List, Dict, Any, Tuple

# ----------------------------------------------------------------------
# Helper to retrieve motion records per frame for a scope
def _motion_frames(doc: Dict, scope: str) -> Dict[int, List[Dict[str, float]]]:
    node = node_by_title(doc, f"{scope}: Motion log")
    frames: Dict[int, List[Dict[str, float]]] = {}
    if not node or node["kind"] != "table":
        return frames
    for idx, row in table_rows(node):
        try:
            f = int(row["frame"])
            oid = re.search(r"(\d+)\s", row["object"]).group(1)
            r = {
                "id": oid,
                "x": float(row["x"]),
                "y": float(row["y"]),
                "vx": float(row["vx"]),
                "vy": float(row["vy"]),
            }
            frames.setdefault(f, []).append(r)
        except Exception:
            continue
    return frames

# ----------------------------------------------------------------------
# Derive a collision distance threshold from all observed collisions
def _derived_collision_threshold(doc: Dict) -> float:
    dists = []
    for n in doc["nodes"]:
        if not n["title"].startswith("Video "):
            continue
        ev_node = node_by_title(doc, f"{n['title']}: Events")
        mo_node = node_by_title(doc, f"{n['title']}: Motion log")
        if not ev_node or not mo_node:
            continue
        # per frame lookup
        frame_map: Dict[int, List[Dict[str, str]]] = {}
        for idx, row in table_rows(mo_node):
            f = int(row["frame"])
            frame_map.setdefault(f, []).append(row)
        for line in ev_node["lines"]:
            if "collide" not in line.lower():
                continue
            obj_ids = _extract_objects(line)
            if len(obj_ids) < 2:
                continue
            f = _extract_frame(line)
            if f is None:
                continue
            objs = {}
            for r in frame_map.get(f, []):
                if r["object"].startswith(obj_ids[0]):
                    objs[obj_ids[0]] = (float(r["x"]), float(r["y"]))
                if r["object"].startswith(obj_ids[1]):
                    objs[obj_ids[1]] = (float(r["x"]), float(r["y"]))
            if len(objs) == 2:
                a, b = obj_ids[:2]
                d = math.hypot(objs[a][0]-objs[b][0], objs[a][1]-objs[b][1])
                dists.append(d)
    if not dists:
        return 0.5  # fallback
    # Use a threshold that is a bit above the median to avoid early detection
    dists.sort()
    med = dists[len(dists)//2]
    return med * 1.05  # ~5% head‑room

# ----------------------------------------------------------------------
# Interpolate position of an entity at a given integer frame
def _pos_at(timeline: List[Tuple[int, Dict[str, float]]], f: int) -> Tuple[float, float]:
    if not timeline:
        return (0.0, 0.0)
    if f <= timeline[0][0]:
        return (timeline[0][1]["x"], timeline[0][1]["y"])
    for i in range(1, len(timeline)):
        f0, r0 = timeline[i-1]
        f1, r1 = timeline[i]
        if f == f0:
            return (r0["x"], r0["y"])
        if f < f1:
            frac = (f - f0) / (f1 - f0)
            x = r0["x"] + (r1["x"] - r0["x"]) * frac
            y = r0["y"] + (r1["y"] - r0["y"]) * frac
            return (x, y)
    # beyond last record
    return (timeline[-1][1]["x"], timeline[-1][1]["y"])

# ----------------------------------------------------------------------
# Main simulation routine
def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, float], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    # boundaries
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 5.0

    start_f = int(round(start / 0.05))
    end_f = int(round(horizon / 0.05))

    # entity set from inputs
    input_ids = {inp["entities"][0] for inp in inputs}

    # motion frame data
    frames = _motion_frames(doc, scope)

    # build timelines per entity
    timelines: Dict[str, List[Tuple[int, Dict[str, float]]]] = {}
    for f, recs in frames.items():
        for r in recs:
            timelines.setdefault(r["id"], []).append((f, r))
    for lst in timelines.values():
        lst.sort(key=lambda x: x[0])

    # collision threshold
    thresh = _derived_collision_threshold(doc)

    # state: previous distance per pair
    prev_dist: Dict[Tuple[str, str], float] = {}

    outcomes: List[Dict[str, Any]] = []

    for f in range(start_f, end_f + 1):
        present = [r["id"] for r in frames.get(f, []) if r["id"] in input_ids]
        # compare every unordered pair
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                a, b = present[i], present[j]
                key = tuple(sorted((a, b)))
                # distance at frame f
                xa, ya = _pos_at(timelines[a], f)
                xb, yb = _pos_at(timelines[b], f)
                d = math.hypot(xa - xb, ya - yb)
                # collision detection: distance crossing below threshold
                prev = prev_dist.get(key, None)
                if prev is None and d <= thresh:
                    # first observation under threshold -> consider as collision
                    coll = {
                        "time": f * 0.05,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [["simulated", f, key]]
                    }
                    outcomes.append(coll)
                elif prev is not None and prev > thresh and d <= thresh:
                    coll = {
                        "time": f * 0.05,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [["simulated", f, key]]
                    }
                    outcomes.append(coll)
                prev_dist[key] = d

    # order by time
    outcomes.sort(key=lambda o: o["time"])
    return outcomes

