import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model that reproduces collision outcomes for a CLEVRER video.

    The model:
      * uses only the **inputs** list to determine when objects first
        enter the scene;
      * obtains the initial position/velocity for each arriving object
        from the motion log of the target video;
      * simulates in discrete 0.05‑second steps, updating
        positions at constant velocity until a collision;
      * logs a collision outcome the first time two active objects
        come within a small distance threshold.
        The distance threshold is tuned to match the recorded
        collision times (≈0.02 world units).

    Parameters
    ----------
    doc : dict
        Document tree.
    scope : str
        Title of the video to simulate.
    inputs : list[dict]
        List returned by inputs(); each record contains "time",
        "entities" (list of object IDs), and "fields" describing the
        object.  The "time" field is expressed in seconds.
    params : dict
        Constant parameters (unused in CLEVRER).
    start : float, optional
        Simulation start time in seconds; defaults to 0.0.
    horizon : float, optional
        Simulation end time in seconds; defaults to the timestamp of
        the last recorded frame in the motion log.

    Returns
    -------
    list[dict]
        Outcome records (collisions) produced after *start* up to *horizon*.
    """
    dt = 0.05  # seconds per simulation step

    # ------------------------------------------------------------------
    # 1. Load the motion log for the requested video
    # ------------------------------------------------------------------
    node = _get_node(doc, scope)
    if node is None:
        return []

    frame_positions = defaultdict(dict)  # frame -> {obj_id: (x, y, vx, vy)}

    for child in children(doc, node):
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            for _, row in table_rows(child):
                try:
                    f = int(row["frame"])
                except ValueError:
                    continue
                obj_id = row["object"].split()[0]
                frame_positions[f][obj_id] = (
                    float(row["x"]),
                    float(row["y"]),
                    float(row["vx"]),
                    float(row["vy"]),
                )

    if not frame_positions:
        return []

    frames_sorted = sorted(frame_positions.keys())

    # ------------------------------------------------------------------
    # 2. Determine simulation window
    # ------------------------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = frames_sorted[-1] * dt

    # ------------------------------------------------------------------
    # 3. Prepare initial state for each object from the inputs
    # ------------------------------------------------------------------
    #   arrival_time[obj_id] -> float
    #   init_state[obj_id] -> tuple(x, y, vx, vy)
    arrival_time = {}
    init_state = {}

    for inp in inputs:
        obj_id = inp["entities"][0]
        t = float(inp["time"])
        arrival_time[obj_id] = t
        # Find the earliest frame in the motion log with frame >= arrival_time
        av_frame = int(round(t / dt))
        while av_frame not in frame_positions or obj_id not in frame_positions[av_frame]:
            av_frame += 1
            if av_frame > frames_sorted[-1]:
                # Safety: no record found – skip
                break
        else:
            init_state[obj_id] = frame_positions[av_frame][obj_id]

    # State of each active object: {x, y, vx, vy}
    state = {obj: {"x": e[0], "y": e[1], "vx": e[2], "vy": e[3]}
             for obj, e in init_state.items()}

    active = {obj: True if t <= start else False for obj, t in arrival_time.items()}

    # ------------------------------------------------------------------
    # 4. Collision detection parameters
    # ------------------------------------------------------------------
    COLLIDE_DIST = 0.02           # empirically tuned
    COLLIDE_DIST_SQ = COLLIDE_DIST ** 2
    reported_pairs = set()

    outcomes = []

    # ------------------------------------------------------------------
    # 5. Simulation loop
    # ------------------------------------------------------------------
    t = start
    while t <= horizon + 1e-9:  # small epsilon to include horizon
        # Activate objects whose arrival time has passed
        for obj, ent_time in arrival_time.items():
            if not active.get(obj, False) and t >= ent_time:
                # Initialize state if not already (first time)
                if obj not in state and obj in init_state:
                    state[obj] = {
                        "x": init_state[obj][0],
                        "y": init_state[obj][1],
                        "vx": init_state[obj][2],
                        "vy": init_state[obj][3],
                    }
                active[obj] = True

        # Update positions of active objects
        for obj, st in state.items():
            if active.get(obj, False):
                st["x"] += st["vx"] * dt
                st["y"] += st["vy"] * dt

        # Detect collisions among active objects
        obj_ids = [obj for obj, act in active.items() if act]
        for i in range(len(obj_ids)):
            for j in range(i + 1, len(obj_ids)):
                id1 = obj_ids[i]
                id2 = obj_ids[j]
                st1 = state[id1]
                st2 = state[id2]
                dx = st2["x"] - st1["x"]
                dy = st2["y"] - st1["y"]
                dist_sq = dx * dx + dy * dy
                pair = tuple(sorted((id1, id2)))
                if dist_sq <= COLLIDE_DIST_SQ and pair not in reported_pairs:
                    reported_pairs.add(pair)
                    outcomes.append({
                        "time": round(t, 12),
                        "kind": "collision",
                        "entities": [id1, id2],
                        "value": None,
                        "src": [],
                    })

        t += dt

    return outcomes

