        return frames
    for idx, row in table_rows(node):
        try:
            f = int(row["frame"])
            oid = re.search(r"(\d+)\s", row["object"]).group(1)
            r = {
                "id": oid,
                "x": float(row["x"]),
                "y": float(row["y"]),
                "vx": float(row["vx"]),
                "vy": float(row["vy"]),
            }
            frames.setdefault(f, []).append(r)
        except Exception:
            continue
    return frames

