        f1, r1 = timeline[i]
        if f == f0:
            return (r0["x"], r0["y"])
        if f < f1:
            frac = (f - f0) / (f1 - f0)
            x = r0["x"] + (r1["x"] - r0["x"]) * frac
            y = r0["y"] + (r1["y"] - r0["y"]) * frac
            return (x, y)
    # beyond last record
    return (timeline[-1][1]["x"], timeline[-1][1]["y"])

# ----------------------------------------------------------------------
# Main simulation routine
def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, float], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    # boundaries
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start + 5.0

    start_f = int(round(start / 0.05))
    end_f = int(round(horizon / 0.05))

    # entity set from inputs
    input_ids = {inp["entities"][0] for inp in inputs}

    # motion frame data
    frames = _motion_frames(doc, scope)

    # build timelines per entity
    timelines: Dict[str, List[Tuple[int, Dict[str, float]]]] = {}
    for f, recs in frames.items():
        for r in recs:
            timelines.setdefault(r["id"], []).append((f, r))
    for lst in timelines.values():
        lst.sort(key=lambda x: x[0])

    # collision threshold
    thresh = _derived_collision_threshold(doc)

    # state: previous distance per pair
    prev_dist: Dict[Tuple[str, str], float] = {}

    outcomes: List[Dict[str, Any]] = []

    for f in range(start_f, end_f + 1):
        present = [r["id"] for r in frames.get(f, []) if r["id"] in input_ids]
        # compare every unordered pair
        for i in range(len(present)):
            for j in range(i + 1, len(present)):
                a, b = present[i], present[j]
                key = tuple(sorted((a, b)))
                # distance at frame f
                xa, ya = _pos_at(timelines[a], f)
                xb, yb = _pos_at(timelines[b], f)
                d = math.hypot(xa - xb, ya - yb)
                # collision detection: distance crossing below threshold
                prev = prev_dist.get(key, None)
                if prev is None and d <= thresh:
                    # first observation under threshold -> consider as collision
                    coll = {
                        "time": f * 0.05,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [["simulated", f, key]]
                    }
                    outcomes.append(coll)
                elif prev is not None and prev > thresh and d <= thresh:
                    coll = {
                        "time": f * 0.05,
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": [["simulated", f, key]]
                    }
                    outcomes.append(coll)
                prev_dist[key] = d

    # order by time
    outcomes.sort(key=lambda o: o["time"])
    return outcomes
